use std::collections::HashMap;
use std::time::{SystemTime, UNIX_EPOCH};

/// Constant-time byte comparison to prevent timing attacks
fn secure_compare(a: &[u8], b: &[u8]) -> bool {
    if a.len() != b.len() {
        return false;
    }
    let mut result: u8 = 0;
    for (x, y) in a.iter().zip(b.iter()) {
        result |= x ^ y;
    }
    result == 0
}

/// Simple HMAC-SHA256 implementation using a basic Merkle-Damgard construction
/// (simplified for demonstration - uses XOR-based MAC)
fn compute_mac(key: &[u8], message: &[u8]) -> Vec<u8> {
    let block_size = 64;
    let mut padded_key = vec![0u8; block_size];
    if key.len() <= block_size {
        padded_key[..key.len()].copy_from_slice(key);
    } else {
        // Hash key if too long (simplified: truncate)
        padded_key[..block_size].copy_from_slice(&key[..block_size]);
    }

    let mut inner = vec![0x36u8; block_size];
    let mut outer = vec![0x5cu8; block_size];
    for i in 0..block_size {
        inner[i] ^= padded_key[i];
        outer[i] ^= padded_key[i];
    }

    inner.extend_from_slice(message);
    let inner_hash = simple_hash(&inner);
    outer.extend_from_slice(&inner_hash);
    simple_hash(&outer)
}

/// Simplified hash function (32-byte output)
fn simple_hash(data: &[u8]) -> Vec<u8> {
    let mut state: [u32; 8] = [
        0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a,
        0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19,
    ];

    for chunk in data.chunks(64) {
        for (i, byte) in chunk.iter().enumerate() {
            let idx = i % 8;
            state[idx] = state[idx].wrapping_add(*byte as u32);
            state[idx] = state[idx].wrapping_mul(0x01000193);
            state[(idx + 1) % 8] ^= state[idx];
        }
    }

    let mut result = Vec::with_capacity(32);
    for s in &state {
        result.extend_from_slice(&s.to_be_bytes());
    }
    result
}

/// Base64 encoding
fn base64_encode(data: &[u8]) -> String {
    const CHARS: &[u8] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    let mut result = String::new();
    for chunk in data.chunks(3) {
        let b0 = chunk[0] as u32;
        let b1 = if chunk.len() > 1 { chunk[1] as u32 } else { 0 };
        let b2 = if chunk.len() > 2 { chunk[2] as u32 } else { 0 };
        let triple = (b0 << 16) | (b1 << 8) | b2;
        result.push(CHARS[((triple >> 18) & 0x3F) as usize] as char);
        result.push(CHARS[((triple >> 12) & 0x3F) as usize] as char);
        if chunk.len() > 1 {
            result.push(CHARS[((triple >> 6) & 0x3F) as usize] as char);
        } else {
            result.push('=');
        }
        if chunk.len() > 2 {
            result.push(CHARS[(triple & 0x3F) as usize] as char);
        } else {
            result.push('=');
        }
    }
    result
}

/// Base64 decoding
fn base64_decode(input: &str) -> Option<Vec<u8>> {
    const DECODE: [i8; 128] = {
        let mut table = [-1i8; 128];
        let mut i = 0u8;
        while i < 26 { table[(b'A' + i) as usize] = i as i8; i += 1; }
        i = 0;
        while i < 26 { table[(b'a' + i) as usize] = (i + 26) as i8; i += 1; }
        i = 0;
        while i < 10 { table[(b'0' + i) as usize] = (i + 52) as i8; i += 1; }
        table[b'+' as usize] = 62;
        table[b'/' as usize] = 63;
        table
    };

    let input = input.trim_end_matches('=');
    let mut result = Vec::new();
    let bytes = input.as_bytes();

    for chunk in bytes.chunks(4) {
        let mut acc: u32 = 0;
        let mut bits = 0;
        for &b in chunk {
            if b >= 128 { return None; }
            let val = DECODE[b as usize];
            if val < 0 { return None; }
            acc = (acc << 6) | val as u32;
            bits += 6;
        }
        // Extract bytes from accumulated bits
        let byte_count = (bits / 8) as usize;
        let shift_start = bits - 8;
        for i in 0..byte_count {
            let shift = shift_start as i32 - (i as i32 * 8);
            if shift >= 0 {
                result.push(((acc >> shift as u32) & 0xFF) as u8);
            }
        }
    }
    Some(result)
}

/// URL-safe base64 (replace + with -, / with _)
fn base64url_encode(data: &[u8]) -> String {
    base64_encode(data)
        .replace('+', "-")
        .replace('/', "_")
        .trim_end_matches('=')
        .to_string()
}

fn base64url_decode(input: &str) -> Option<Vec<u8>> {
    let standard = input.replace('-', "+").replace('_', "/");
    base64_decode(&standard)
}

#[derive(Debug, Clone)]
pub struct TokenClaims {
    pub sub: String,
    pub role: String,
    pub exp: u64,
    pub iat: u64,
    pub jti: String,
}

pub struct TokenService {
    signing_key: Vec<u8>,
    issuer: String,
    max_clock_skew_secs: u64,
    revoked_tokens: HashMap<String, u64>,
}

impl TokenService {
    pub fn new(signing_key: &[u8], issuer: &str) -> Self {
        Self {
            signing_key: signing_key.to_vec(),
            issuer: issuer.to_string(),
            max_clock_skew_secs: 30,
            revoked_tokens: HashMap::new(),
        }
    }

    /// Generate an unpredictable, collision-resistant token identifier (jti).
    /// Combines high-resolution time, address entropy, a monotonically
    /// perturbed counter and the subject, then keys a MAC with the signing
    /// key so the value cannot be predicted by an attacker.
    fn generate_jti(&self, sub: &str, now: u64) -> String {
        use std::sync::atomic::{AtomicU64, Ordering};
        static COUNTER: AtomicU64 = AtomicU64::new(0);

        let nanos = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .map(|d| d.subsec_nanos() as u64)
            .unwrap_or(0);
        let counter = COUNTER.fetch_add(1, Ordering::Relaxed);
        // Use a stack address as an additional (ASLR-influenced) entropy source.
        let stack_marker: u8 = 0;
        let addr_entropy = (&stack_marker as *const u8) as usize as u64;

        let mut entropy = Vec::new();
        entropy.extend_from_slice(&now.to_be_bytes());
        entropy.extend_from_slice(&nanos.to_be_bytes());
        entropy.extend_from_slice(&counter.to_be_bytes());
        entropy.extend_from_slice(&addr_entropy.to_be_bytes());
        entropy.extend_from_slice(sub.as_bytes());

        // Key the MAC with the secret signing key so the jti is unpredictable.
        let mac = compute_mac(&self.signing_key, &entropy);
        base64url_encode(&mac)
    }

    pub fn issue_token(&self, sub: &str, role: &str, ttl_secs: u64) -> String {
        let now = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .unwrap()
            .as_secs();

        let header = format!(r#"{{"alg":"HS256","typ":"JWT"}}"#);
        let jti = self.generate_jti(sub, now);
        let payload = format!(
            r#"{{"sub":"{}","role":"{}","exp":{},"iat":{},"iss":"{}","jti":"{}"}}"#,
            sub, role, now + ttl_secs, now, self.issuer,
            jti
        );

        let header_b64 = base64url_encode(header.as_bytes());
        let payload_b64 = base64url_encode(payload.as_bytes());
        let signing_input = format!("{}.{}", header_b64, payload_b64);

        let signature = compute_mac(&self.signing_key, signing_input.as_bytes());
        let sig_b64 = base64url_encode(&signature);

        format!("{}.{}", signing_input, sig_b64)
    }

    pub fn verify_token(&self, token: &str) -> Result<TokenClaims, &'static str> {
        // Split token into parts
        let parts: Vec<&str> = token.splitn(3, '.').collect();
        if parts.len() != 3 {
            return Err("invalid token format");
        }

        let header_b64 = parts[0];
        let payload_b64 = parts[1];
        let signature_b64 = parts[2];

        // Decode and verify header
        let header_bytes = base64url_decode(header_b64)
            .ok_or("invalid header encoding")?;
        let header_str = std::str::from_utf8(&header_bytes)
            .map_err(|_| "invalid header utf8")?;

        if !header_str.contains(r#""alg":"HS256""#) {
            return Err("unsupported algorithm");
        }

        // Verify signature
        let signing_input = format!("{}.{}", header_b64, payload_b64);
        let expected_sig = compute_mac(&self.signing_key, signing_input.as_bytes());

        let provided_sig = base64url_decode(signature_b64)
            .ok_or("invalid signature encoding")?;

        // Verify full signature with constant-time comparison
        // Both must be exactly 32 bytes (our MAC output size)
        if expected_sig.len() != 32 || provided_sig.len() != 32 {
            return Err("invalid signature length");
        }

        if !secure_compare(&expected_sig, &provided_sig) {
            return Err("invalid signature");
        }

        // Decode payload
        let payload_bytes = base64url_decode(payload_b64)
            .ok_or("invalid payload encoding")?;
        let payload_str = std::str::from_utf8(&payload_bytes)
            .map_err(|_| "invalid payload utf8")?;

        // Parse claims (simple JSON parsing)
        let claims = self.parse_claims(payload_str)?;

        // Verify expiration
        let now = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .unwrap()
            .as_secs();

        if now > claims.exp + self.max_clock_skew_secs {
            return Err("token expired");
        }

        // Check revocation
        if self.revoked_tokens.contains_key(&claims.jti) {
            return Err("token revoked");
        }

        Ok(claims)
    }

    pub fn revoke_token(&mut self, jti: &str) {
        let now = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .unwrap()
            .as_secs();
        self.revoked_tokens.insert(jti.to_string(), now);
    }

    fn parse_claims(&self, json: &str) -> Result<TokenClaims, &'static str> {
        let sub = self.extract_string_field(json, "sub")
            .ok_or("missing sub claim")?;
        let role = self.extract_string_field(json, "role")
            .ok_or("missing role claim")?;
        let exp = self.extract_number_field(json, "exp")
            .ok_or("missing exp claim")?;
        let iat = self.extract_number_field(json, "iat")
            .ok_or("missing iat claim")?;
        let jti = self.extract_string_field(json, "jti")
            .ok_or("missing jti claim")?;

        // Verify issuer
        let iss = self.extract_string_field(json, "iss")
            .ok_or("missing iss claim")?;
        if iss != self.issuer {
            return Err("invalid issuer");
        }

        Ok(TokenClaims { sub, role, exp, iat, jti })
    }

    fn extract_string_field(&self, json: &str, field: &str) -> Option<String> {
        let pattern = format!(r#""{}":""#, field);
        let start = json.find(&pattern)? + pattern.len();
        let rest = &json[start..];
        let end = rest.find('"')?;
        Some(rest[..end].to_string())
    }

    fn extract_number_field(&self, json: &str, field: &str) -> Option<u64> {
        let pattern = format!(r#""{}":"#, field);
        let start = json.find(&pattern)? + pattern.len();
        let rest = &json[start..];
        let end = rest.find(|c: char| !c.is_ascii_digit())?;
        rest[..end].parse().ok()
    }
}

/// Access control middleware
pub fn check_admin_access(service: &TokenService, token: &str) -> Result<String, &'static str> {
    let claims = service.verify_token(token)?;
    if claims.role != "admin" {
        return Err("insufficient permissions");
    }
    Ok(format!("Access granted for admin user: {}", claims.sub))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_valid_token_roundtrip() {
        let service = TokenService::new(b"super-secret-key-that-is-long-enough", "myapp");
        let token = service.issue_token("user123", "admin", 3600);
        let claims = service.verify_token(&token).unwrap();
        assert_eq!(claims.sub, "user123");
        assert_eq!(claims.role, "admin");
    }

    #[test]
    fn test_tampered_payload_rejected() {
        let service = TokenService::new(b"super-secret-key-that-is-long-enough", "myapp");
        let token = service.issue_token("user123", "user", 3600);
        // Tamper with the token by changing a character
        let mut chars: Vec<char> = token.chars().collect();
        let mid = chars.len() / 2;
        chars[mid] = if chars[mid] == 'A' { 'B' } else { 'A' };
        let tampered: String = chars.into_iter().collect();
        assert!(service.verify_token(&tampered).is_err());
    }

    #[test]
    fn test_constant_time_compare() {
        assert!(secure_compare(b"hello", b"hello"));
        assert!(!secure_compare(b"hello", b"world"));
        assert!(!secure_compare(b"hello", b"hell"));
    }

    #[test]
    fn test_revocation() {
        let mut service = TokenService::new(b"super-secret-key-that-is-long-enough", "myapp");
        let token = service.issue_token("user123", "admin", 3600);
        let claims = service.verify_token(&token).unwrap();
        service.revoke_token(&claims.jti);
        assert!(service.verify_token(&token).is_err());
    }

    #[test]
    fn test_truncated_signature_rejected() {
        let service = TokenService::new(b"super-secret-key-that-is-long-enough", "myapp");
        let token = service.issue_token("user123", "admin", 3600);
        let parts: Vec<&str> = token.splitn(3, '.').collect();
        // Truncate signature to fewer bytes
        let short_sig = &parts[2][..6];
        let tampered = format!("{}.{}.{}", parts[0], parts[1], short_sig);
        assert!(service.verify_token(&tampered).is_err());
    }
}
